const assert=require('node:assert/strict')
const fs=require('node:fs/promises')
const {chromium,resultScenario,resultStep,screenshot}=require('../../playwright/harness')
const {openBenchmark}=require('../../playwright/offline')
resultScenario({title:'Настройки, остановка, сведения о компьютере и CSV',group:'entities'})
async function main(){
	console.log('OWNER',JSON.stringify({pid:process.pid,deadline_ms:180000}))
	const browser=await chromium.launch({headless:true,channel:'chrome'})
	const deadline=setTimeout(()=>browser.close().catch(()=>{}),180000)
	const held=[]
	let built
	try{
		if(process.env.RISE_TEST_BUILT==='1')built=await require('../../playwright/built').serveBuilt()
		const context=await browser.newContext({viewport:{width:1600,height:1000},permissions:['clipboard-read','clipboard-write']})
		const page=await context.newPage();page.setDefaultTimeout(20000);page.setDefaultNavigationTimeout(90000)
		const errors=[];page.on('pageerror',error=>errors.push(error.message))
		const url=new URL(built?.url||process.env.RISE_TEST_URL||'http://localhost:9080/rise/app/-/test.html')
		url.searchParams.set('rise_fixture','sqltests');url.hash='!=bench/bench=%24rise_bench_baza_goods'
		await openBenchmark(page,url.href)
		const engine=page.locator('[rise_bench_host_controls_engine]'),count=page.locator('[rise_bench_host_controls_count]'),schema=page.locator('[rise_bench_host_controls_schema]')
		const option=(group,label)=>group.getByRole('checkbox',{name:label,exact:true})
		const run=page.getByRole('button',{name:'Запустить бенчмарк',exact:true})
		await page.waitForFunction(()=>globalThis.$?.$rise_app.Root(0).Bench().Goods_host().run_enabled())
		resultStep('Прочитать описание и выбрать несколько вариантов',['$rise_check_list.all_checked','$rise_bench_host.selected_engines','$rise_bench_batch'])
		assert.equal(await engine.getByRole('checkbox').first().innerText(),'Все')
		assert.equal(await option(engine,'Гипербаза').getAttribute('aria-checked'),'true')
		assert.equal(await option(count,'100').getAttribute('aria-checked'),'true')
		assert.equal(await option(schema,'4 свойства').getAttribute('aria-checked'),'true')
		await page.getByText('Версия бенчмарка: 0.6.0.',{exact:false}).waitFor()
		console.log('SETTINGS_SCREENSHOT',await screenshot(page,'controls-settings.png'))
		await option(engine,'IDB').click();await option(count,'500').click();await option(schema,'10 свойств').click()
		assert.equal(await page.evaluate(()=>{const h=$.$rise_app.Root(0).Bench().Goods_host();return $.$rise_bench_batch(h.engine(),h.count(),h.schema()).length}),8)
		await option(engine,'Все').click();await option(count,'Все').click()
		assert.equal(await page.evaluate(()=>{const h=$.$rise_app.Root(0).Bench().Goods_host();return $.$rise_bench_batch(h.engine(),h.count(),h.schema()).length}),100)
		await option(engine,'Все').click();await page.waitForFunction(()=>!$.$rise_app.Root(0).Bench().Goods_host().run_enabled());assert.notEqual(await run.getAttribute('disabled'),null)
		await option(engine,'IDB').click()
		await option(count,'Все').click();await option(count,'100').click()
		await option(schema,'Все').click();await option(schema,'4 свойства').click()
		resultStep('Открыть подсказку Windows и вставить характеристики',['$rise_bench_host_controls_computerhelp','$rise_bench_computer.clean'])
		const help=page.locator('[rise_bench_host_controls_computerhelp] [mol_pick_trigger]')
		await help.click();await page.getByRole('link',{name:'Инструкция Microsoft',exact:true}).waitFor()
		await page.keyboard.press('Escape');await page.getByRole('link',{name:'Инструкция Microsoft',exact:true}).waitFor({state:'detached'})
		await help.click();await page.locator('[rise_bench_host_controls_intro]').click()
		await page.getByRole('link',{name:'Инструкция Microsoft',exact:true}).waitFor({state:'detached'})
		const input=page.getByRole('textbox',{name:'Процессор, память, ОС',exact:true})
		const copied='Имя устройства\tTEST-PC\nПроцессор\tTest CPU\nОперативная память\t32 ГБ\nКод устройства\t12345678-1234-1234-1234-123456789abc\nКод продукта\t00331-20020-00000-AA700\nТип системы\t64-разрядная ОС, процессор x64'
		const cleaned='Имя устройства\tTEST-PC\nПроцессор\tTest CPU\nОперативная память\t32 ГБ\nТип системы\t64-разрядная ОС, процессор x64'
		await page.evaluate(text=>navigator.clipboard.writeText(text),copied)
		await input.focus();await page.keyboard.press('Control+V')
		await page.waitForFunction(expected=>document.querySelector('[rise_bench_host_controls_computer] textarea')?.value===expected,cleaned)
		await run.click();await page.waitForFunction(()=>{const h=$.$rise_app.Root(0).Bench().Goods_host();return !h.busy()&&h.runs().some(row=>row.engine==='idb'&&row.state()==='Готово')})
		assert.match(await page.locator('[rise_bench_host_controls_elapsed]').innerText(),/Текущий этап: \d\d:\d\d:\d\d · Всего: \d\d:\d\d:\d\d/)
		resultStep('Скопировать сведения и скачать CSV',['$rise_bench_metrics_details.Copy','$rise_bench_host.csv_blob'])
		await page.locator('[rise_bench_metrics_details_trigger]').first().click()
		await page.locator('[rise_bench_metrics_details_copy]').click()
		assert.equal((await page.evaluate(()=>navigator.clipboard.readText())).replace(/\r\n/g,'\n'),cleaned)
		await page.keyboard.press('Escape')
		const [download]=await Promise.all([page.waitForEvent('download'),page.getByRole('button',{name:'Скачать CSV',exact:true}).click()])
		const csv=await fs.readFile(await download.path(),'utf8')
		assert.ok(csv.startsWith('\uFEFF'));assert.ok(csv.includes('"Компьютер"')&&csv.includes('"Браузер"')&&csv.includes('Test CPU'))
		assert.ok(!csv.includes('Код устройства')&&!csv.includes('00331-20020'))
		console.log('DESKTOP_SCREENSHOT',await screenshot(page,'controls-desktop.png'))
		resultStep('Дождаться более пяти минут на управляемых часах и остановить вручную',['$rise_bench_host.elapsed_text','$rise_bench_host.stop'])
		await context.route('https://cdn.jsdelivr.net/npm/@sqlite.org/sqlite-wasm@*/**',route=>held.push(route))
		await option(engine,'IDB').click();await option(engine,'SQLite').click()
		await page.waitForFunction(()=>$.$rise_app.Root(0).Bench().Goods_host().run_enabled())
		await page.clock.install()
		await run.click()
		await page.waitForFunction(()=>$.$rise_app.Root(0).Bench().Goods_host().progress?.operation==='Запуск БД, с')
		await page.clock.fastForward(301000)
		assert.equal(await page.evaluate(()=>$.$rise_app.Root(0).Bench().Goods_host().busy()),true,'No automatic timeout after 300 seconds')
		assert.match(await page.locator('[rise_bench_host_controls_elapsed]').innerText(),/00:05:/)
		await page.getByRole('button',{name:'Остановить',exact:true}).click()
		await page.waitForFunction(()=>{const h=$.$rise_app.Root(0).Bench().Goods_host();return !h.busy()&&h.outbox().length===0&&h.runs().some(row=>row.state()==='Остановлено')})
		const frozen=await page.locator('[rise_bench_host_controls_elapsed]').innerText()
		await page.clock.fastForward(60000)
		assert.equal(await page.locator('[rise_bench_host_controls_elapsed]').innerText(),frozen)
		assert.equal(await page.getByRole('button',{name:'Остановить',exact:true}).count(),0)
		assert.equal(await page.evaluate(()=>$.$rise_app.Root(0).Bench().Goods_host().active_case()),null)
		for(const route of held)await route.abort().catch(()=>{})
		await context.unroute('https://cdn.jsdelivr.net/npm/@sqlite.org/sqlite-wasm@*/**')
		await page.clock.resume()
		resultStep('Запустить снова после остановки и проверить узкую светлую страницу',['$rise_bench_host.run'])
		await option(engine,'SQLite').click();await option(engine,'IDB').click()
		await page.waitForFunction(()=>$.$rise_app.Root(0).Bench().Goods_host().run_enabled())
		await run.click();await page.waitForFunction(()=>{const h=$.$rise_app.Root(0).Bench().Goods_host();return !h.busy()&&h.runs().filter(row=>row.engine==='idb'&&row.state()==='Готово').length===2})
		await page.setViewportSize({width:390,height:900});await page.emulateMedia({colorScheme:'light'})
		await page.evaluate(()=>document.documentElement.setAttribute('mol_theme','$mol_theme_light'))
		console.log('NARROW_SCREENSHOT',await screenshot(page,'controls-light-narrow.png'))
		assert.deepEqual(errors,[])
		console.log('CONTROLS_PASS',JSON.stringify({csv:download.suggestedFilename(),manualStop:true,elapsedBeyond300:true,defaultEngine:'goods',defaultCount:100}))
		await context.close()
	}finally{for(const route of held)await route.abort().catch(()=>{});clearTimeout(deadline);await browser.close();await built?.close()}
}
main().catch(error=>{console.error(error);process.exitCode=1})
